import {test,expect} from '@playwright/test';
import {registry} from '../src/registry.js';
import {choose} from './ui-helpers.js';
// Independent scoring facts, not expected outputs generated by calculate().
const tables={
 apgar:Object.fromEntries(['appearance','pulse','grimace','activity','respiration'].map(k=>[k,[0,1,2]])),
 'ciwa-ar':Object.fromEntries(['nausea','tremor','sweats','anxiety','agitation','tactile','auditory','visual','headache','orientation'].map(k=>[k,Array.from({length:k==='orientation'?5:8},(_,i)=>i)])),
 'westley-croup':{consciousness:[0,5],cyanosis:[0,4,5],stridor:[0,1,2],airEntry:[0,1,2],retractions:[0,1,2,3]}
};
test('Batch A compiled every independent score component option offline',async({page})=>{
 test.setTimeout(180000);await page.goto('/');await expect(page.locator('h1')).toBeVisible();await page.context().setOffline(true);
 const logs=[],requests=[];page.on('console',m=>logs.push(m.text()));page.on('pageerror',e=>logs.push(e.message));page.on('request',r=>requests.push(r.url()));
 for(const [id,table]of Object.entries(tables)){
  await choose(page,id);if(id==='apgar')await page.locator('#cpc-timepoint').selectOption('5min');
  for(const field of Object.keys(table))await page.locator('#cpc-'+field).selectOption('0');
  for(const [field,levels]of Object.entries(table))for(const n of levels){await page.locator('#cpc-'+field).selectOption(String(n));await page.getByRole('button',{name:'Calculate',exact:true}).click();await expect(page.locator('.cpc-values dd').first()).toContainText(`${n} points`);await page.locator('#cpc-'+field).selectOption('0');}
 }
 await choose(page,'ariscat');const d=registry.find(d=>d.id==='ariscat');
 for(const [field,options]of Object.entries({respiratoryInfection:[['no',0],['yes',17]],incision:[['peripheral',0],['upper-abdominal',15],['intrathoracic',24]],duration:[['le2h',0],['2to3h',16],['gt3h',23]],emergency:[['no',0],['yes',8]]}))for(const [value,n]of options){
  for(const f of d.inputs){const c=page.locator('#cpc-'+f.id);if(f.type==='choice')await c.selectOption(d.vectors[0].inputs[f.id]);else await c.fill(d.vectors[0].inputs[f.id]);}
  await page.locator('#cpc-'+field).selectOption(value);await page.getByRole('button',{name:'Calculate',exact:true}).click();await expect(page.locator('.cpc-values dd').first()).toContainText(`${n} points`);
 }
 await page.locator('#cpc-spo2').fill('95.5');await page.getByRole('button',{name:'Calculate',exact:true}).click();await expect(page.locator('#cpc-spo2-error')).toContainText('whole-number percentage');await expect(page.locator('.cpc-result')).toHaveCount(0);
 expect(logs).toEqual([]);expect(requests).toEqual([]);expect(await page.evaluate(()=>window.probe.storage)).toEqual([]);
});
